const event = msg.payload;
if (!event || typeof event.priceAudMwh !== 'number') {
    node.warn('Dropping message with no priceAudMwh: ' + JSON.stringify(event));
    return null;
}

const THRESHOLD = 300;
if (event.priceAudMwh <= THRESHOLD) {
    return null;
}

msg.payload = {
    type: 'DispatchDecision',
    region: event.region,
    action: 'DISCHARGE',
    reason: `price spike $${event.priceAudMwh}/MWh > $${THRESHOLD} threshold`,
    ts: new Date().toISOString()
};
return msg;
